<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?></title></head><body><main><h1>Initial Student Records administrator setup</h1><p>Development and local browser access only.</p><?php if($error=session()->getFlashdata('error')):?><p role="alert"><?= esc($error) ?></p><?php endif ?><form method="post" action="<?= site_url('admin/setup') ?>"><?= csrf_field() ?><label>One-time setup token<input type="password" name="setup_token" autocomplete="off" required></label><label>Full name<input name="full_name" maxlength="150" required value="<?= esc(session()->getFlashdata('full_name'),'attr') ?>"></label><label>Email<input type="email" name="email" maxlength="150" required value="<?= esc(session()->getFlashdata('email'),'attr') ?>"></label><label>Password<input type="password" name="password" autocomplete="new-password" required></label><label>Confirm password<input type="password" name="password_confirmation" autocomplete="new-password" required></label><button type="submit">Create administrator</button></form></main></body></html>
